var log = new System.Text.StringBuilder();
var pt = System.Type.GetType("Protobot.Editor.Playtest, Protobot.Editor");
System.Action<int> F = n => pt.GetMethod("Frames").Invoke(null, new object[] { n });
System.Action<string, System.Action> Step = (name, a) => { try { a(); F(3); log.Append("ok " + name + "\n"); } catch (System.Exception e) { var x = e.InnerException ?? e; log.Append("FAIL " + name + ": " + x.GetType().Name + " " + x.Message + " @ " + (x.StackTrace ?? "").Split('\n')[0] + "\n"); } };
foreach (var tool in new[] { "Select", "Transform", "Move", "Paint", "Saw", "Drill", "Measure", "Select" }) Step("tool " + tool, () => Protobot.Interface.ToolRail.Select(tool));
Step("Preferences", () => Protobot.Interface.PreferencesWindow.Open());
Step("close dialogs", () => { foreach (var d in UnityEngine.Object.FindObjectsByType<Protobot.Interface.Dialog>(FindObjectsSortMode.None)) d.Close(); });
Step("Keybinds", () => Protobot.Tools.KeybindsWindow.Open());
Step("close dialogs", () => { foreach (var d in UnityEngine.Object.FindObjectsByType<Protobot.Interface.Dialog>(FindObjectsSortMode.None)) d.Close(); });
Step("Graphics", () => Protobot.Interface.GraphicsWindow.Open());
Step("close dialogs", () => { foreach (var d in UnityEngine.Object.FindObjectsByType<Protobot.Interface.Dialog>(FindObjectsSortMode.None)) d.Close(); });
Step("Library", () => Protobot.Custom.LibraryDialog.Open());
Step("close dialogs", () => { foreach (var d in UnityEngine.Object.FindObjectsByType<Protobot.Interface.Dialog>(FindObjectsSortMode.None)) d.Close(); });
Step("Sheets", () => Protobot.Polycarb.SheetsDialog.Open());
Step("close dialogs", () => { foreach (var d in UnityEngine.Object.FindObjectsByType<Protobot.Interface.Dialog>(FindObjectsSortMode.None)) d.Close(); });
Step("ControlsPanel", () => Protobot.Motion.ControlsPanel.Open());
Step("close dialogs", () => { foreach (var d in UnityEngine.Object.FindObjectsByType<Protobot.Interface.Dialog>(FindObjectsSortMode.None)) d.Close(); });
Step("ChainTool", () => Protobot.Motion.ChainTool.Begin());
Step("Esc chain", () => { var m = typeof(Protobot.Motion.ChainTool).GetMethod("End", System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static); if (m != null) m.Invoke(null, m.GetParameters().Length == 0 ? null : new object[m.GetParameters().Length]); });
Step("SheetEditor", () => Protobot.Polycarb.SheetEditor.Open());
Step("close editor", () => { var ed = UnityEngine.Object.FindFirstObjectByType<Protobot.Polycarb.SheetEditor>(); if (ed != null) UnityEngine.Object.Destroy(ed.gameObject); });
Step("Game OpenPlay", () => Protobot.Game.GameUi.OpenPlay());
Step("close dialogs", () => { foreach (var d in UnityEngine.Object.FindObjectsByType<Protobot.Interface.Dialog>(FindObjectsSortMode.None)) d.Close(); });
return log.ToString();
